selector_to_html = {"a[href=\"#flaggems\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5f00\u59cb\u4f7f\u7528 FlagGems<a class=\"headerlink\" href=\"#flaggems\" title=\"Link to this heading\">#</a></h1><h2>1. \u5b89\u88c5 FlagGems {#install-flaggems}<a class=\"headerlink\" href=\"#flaggems-install-flaggems\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> \u53ef\u4ee5\u4ee5\u7eaf Python \u5305\u7684\u5f62\u5f0f\u5b89\u88c5\uff0c\u4e5f\u53ef\u4ee5\u9644\u5e26 C++ \u6269\u5c55\u7279\u6027\u6765\u5b89\u88c5\uff0c\n\u4ee5\u5b9e\u73b0\u66f4\u597d\u7684\u8fd0\u884c\u65f6\u6027\u80fd\u3002\u4f60\u53ef\u4ee5\u53c2\u9605<a class=\"reference internal\" href=\"#../getting-started/installation\"><span class=\"xref myst\">\u5b89\u88c5\u6307\u5357</span></a>\n\u7684\u8bf4\u660e\uff0c\u4e86\u89e3\u4e0d\u540c\u5b89\u88c5\u65b9\u5f0f\u3001\u9009\u9879\u7684\u8be6\u7ec6\u6307\u4ee4\u3002</p>", "a[href=\"#pytorch\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.1 \u68c0\u67e5 PyTorch \u73af\u5883<a class=\"headerlink\" href=\"#pytorch\" title=\"Link to this heading\">#</a></h3><p>\u4f60\u8981\u6267\u884c\u7684\u7b2c\u4e00\u9879\u68c0\u67e5\u662f\u786e\u8ba4\u80fd\u591f\u5728\u4f60\u7684\u5de5\u4f5c\u73af\u5883\u4e2d\u5bfc\u5165 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch</span></code> \u8f6f\u4ef6\u5305\uff1a</p>", "a[href=\"../usage/non-nvidia.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5728\u975e\u82f1\u4f1f\u8fbe\uff08NVIDIA\uff09\u786c\u4ef6\u4e0a\u4f7f\u7528 FlagGems<a class=\"headerlink\" href=\"#nvidia-flaggems\" title=\"Link to this heading\">#</a></h1><h2>1. \u652f\u6301\u7684\u5e73\u53f0<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> \u5728 NVIDIA \u82af\u7247\u4e4b\u5916\u652f\u6301\u82e5\u5e72\u4e0d\u540c\u7c7b\u578b\u7684 AI \u82af\u7247\u6216\u5e73\u53f0\u3002\n\u8bf7\u53c2\u9605<a class=\"reference internal\" href=\"../overview/platforms.html\"><span class=\"doc std std-doc\">\u5e73\u53f0\u652f\u6301</span></a>\n\u6587\u6863\u4e86\u89e3\u5df2\u7ecf\u9a8c\u8bc1\u8fc7\u7684\u5e73\u53f0\u7684\u6700\u65b0\u5217\u8868\u3002</p>", "a[href=\"#triton\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.2 \u68c0\u67e5 Triton \u5b89\u88c5<a class=\"headerlink\" href=\"#triton\" title=\"Link to this heading\">#</a></h3><p>\u63a5\u4e0b\u6765\u7684\u4e00\u9879\u68c0\u67e5\u662f\u9488\u5bf9 <code class=\"docutils literal notranslate\"><span class=\"pre\">triton</span></code> \u8f6f\u4ef6\u5305\u7684\u3002\n\u4f60\u53ef\u4ee5\u4f7f\u7528\u4e0b\u9762\u7684\u547d\u4ee4\u6765\u68c0\u67e5 <code class=\"docutils literal notranslate\"><span class=\"pre\">triton</span></code> \u5305\u662f\u5426\u53ef\u4ee5\u6b63\u5e38\u4f7f\u7528\u3002</p>", "a[href=\"#id2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.3 \u68c0\u67e5 FlagGems \u7684\u5b89\u88c5<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h3><p>\u9488\u5bf9 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> \u5305\uff0c\u4f60\u4e5f\u53ef\u4ee5\u4f7f\u7528\u4e0b\u9762\u7684\u547d\u4ee4\u6267\u884c\u7c7b\u4f3c\u7684\u68c0\u67e5\uff1a</p>", "a[href=\"#flaggems-install-flaggems\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. \u5b89\u88c5 FlagGems {#install-flaggems}<a class=\"headerlink\" href=\"#flaggems-install-flaggems\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> \u53ef\u4ee5\u4ee5\u7eaf Python \u5305\u7684\u5f62\u5f0f\u5b89\u88c5\uff0c\u4e5f\u53ef\u4ee5\u9644\u5e26 C++ \u6269\u5c55\u7279\u6027\u6765\u5b89\u88c5\uff0c\n\u4ee5\u5b9e\u73b0\u66f4\u597d\u7684\u8fd0\u884c\u65f6\u6027\u80fd\u3002\u4f60\u53ef\u4ee5\u53c2\u9605<a class=\"reference internal\" href=\"#../getting-started/installation\"><span class=\"xref myst\">\u5b89\u88c5\u6307\u5357</span></a>\n\u7684\u8bf4\u660e\uff0c\u4e86\u89e3\u4e0d\u540c\u5b89\u88c5\u65b9\u5f0f\u3001\u9009\u9879\u7684\u8be6\u7ec6\u6307\u4ee4\u3002</p>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. \u5f00\u59cb\u4f7f\u7528 FlagGems<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p>\u4f60\u53ef\u4ee5\u7528\u591a\u79cd\u4e0d\u540c\u65b9\u5f0f\u6765\u542f\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> \u6240\u63d0\u4f9b\u7684\u52a0\u901f\u7b97\u5b50\u3002\n\u4e0b\u9762\u7684\u4ee3\u7801\u6bb5\u5728\u5168\u5c40\u8303\u56f4\u5185\u542f\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code>\uff1a</p>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. \u68c0\u67e5\u5b89\u88c5\u72b6\u6001<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p>\u5728\u5b89\u88c5\u4e86 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> \u5305\u53ca\u5176\u6240\u4f9d\u8d56\u7684\u5176\u4ed6\u8f6f\u4ef6\u5305\u4e4b\u540e\uff0c\n\u4f60\u53ef\u80fd\u5e0c\u671b\u68c0\u67e5\u8fd9\u4e9b\u8f6f\u4ef6\u5305\u662f\u5426\u80fd\u591f\u6b63\u5e38\u5de5\u4f5c\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
